-- Batch update templates 15,16,17,18,19,25,26,27,28,29 to full user-provided content.
UPDATE public.prd_templates
SET description = $desc$A detailed checklist for ensuring all aspects of product launch are covered to minimize risks.$desc$,
    structure = $json${"instructions": "Be exhaustive and specific. Each checklist item should be a concrete, verifiable task with a clear definition of done — not a vague category. Organize items chronologically (T-4 weeks, T-2 weeks, T-1 week, launch day, post-launch). Include cross-functional dependencies between teams.", "sections": [{"name": "Pre-Launch (T-4 weeks)", "guidelines": "Tasks to complete well before launch day.\n\n### Product Readiness\n- [ ] All P0 features complete and tested\n- [ ] Beta feedback addressed or triaged\n- [ ] Performance and load testing passed\n- [ ] Security review completed\n- [ ] Accessibility audit passed\n\n### Content & Marketing\n- [ ] Launch blog post drafted and reviewed\n- [ ] Product screenshots and demo video created\n- [ ] Social media posts scheduled\n- [ ] Email announcement drafted\n- [ ] Press/media outreach started (if applicable)\n\n### Internal Readiness\n- [ ] Support team trained on new features\n- [ ] FAQ and help docs written\n- [ ] Internal announcement sent to company"}, {"name": "Pre-Launch (T-1 week)", "guidelines": "Final preparations the week before launch.\n\n### Technical\n- [ ] Staging environment matches production config\n- [ ] Monitoring and alerting configured\n- [ ] Rollback plan documented and tested\n- [ ] Feature flags set to correct state\n- [ ] Database migrations tested in staging\n\n### Marketing\n- [ ] Launch page live (or scheduled)\n- [ ] All marketing materials finalized and approved\n- [ ] Social media queue loaded\n- [ ] Email list segmented and ready\n- [ ] Product Hunt / Hacker News draft prepared (if applicable)\n\n### Team\n- [ ] Launch day schedule shared with team\n- [ ] On-call rotation set for launch day\n- [ ] Escalation contacts identified"}, {"name": "Launch Day", "guidelines": "The day-of execution checklist.\n\n### Morning\n- [ ] Deploy to production\n- [ ] Verify all features working in production\n- [ ] Enable feature flags / remove beta restrictions\n- [ ] Publish launch blog post\n- [ ] Send email announcement\n\n### Midday\n- [ ] Post on social media channels\n- [ ] Submit to Product Hunt / communities\n- [ ] Monitor error rates and performance dashboards\n- [ ] Respond to early user feedback and questions\n\n### End of Day\n- [ ] Review launch day metrics\n- [ ] Address any critical bugs or issues\n- [ ] Send internal recap to team\n- [ ] Celebrate the launch"}, {"name": "Post-Launch (Week 1)", "guidelines": "First week after launch — monitor, respond, and iterate.\n\n### Monitoring\n- [ ] Track key metrics daily (signups, activation, errors)\n- [ ] Monitor support ticket volume and themes\n- [ ] Watch social media mentions and sentiment\n- [ ] Review error tracking (Sentry, LogRocket) for new issues\n\n### Response\n- [ ] Respond to all customer feedback within 24 hours\n- [ ] Triage and fix critical bugs immediately\n- [ ] Publish follow-up content (tips, tutorials, use cases)\n\n### Retrospective\n- [ ] Run launch retrospective with team\n- [ ] Document learnings for next launch\n- [ ] Update launch playbook with improvements"}, {"name": "Post-Launch (Month 1)", "guidelines": "First month — measure success and plan next steps.\n\n### Metrics Review\n- [ ] Compare actual metrics to launch targets\n- [ ] Identify top-performing acquisition channels\n- [ ] Analyze activation funnel drop-off points\n- [ ] Assess early retention signals\n\n### Product Iteration\n- [ ] Prioritize feature requests from launch feedback\n- [ ] Ship quick wins identified during launch week\n- [ ] Plan next release based on user data\n\n### Growth\n- [ ] Double down on channels that worked\n- [ ] Cut or adjust channels that underperformed\n- [ ] Plan second wave of marketing (case studies, webinars, partnerships)"}, {"name": "Launch Roles & Contacts", "guidelines": "Who is responsible for what during the launch.\n\n### Key Roles\n| Role | Person | Responsibility |\n|------|--------|----------------|\n| Launch Lead | [Name] | Overall coordination, go/no-go decision |\n| Engineering | [Name] | Deploy, monitor, hotfix |\n| Marketing | [Name] | Content, social, PR |\n| Support | [Name] | Customer responses, FAQ updates |\n| Design | [Name] | Assets, last-minute visual fixes |\n\n### Escalation Path\n- Critical bug: [Who to contact and how]\n- PR/comms issue: [Who to contact]\n- Go/no-go decision: [Who makes the call]"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Product Launch Checklist$name$;

UPDATE public.prd_templates
SET description = $desc$A comprehensive guide to evaluate and enhance the security of a product, focusing on various aspects such as technical specifications, key features, and risk assessment.$desc$,
    structure = $json${"instructions": "Be specific to the product’s actual architecture and tech stack — avoid generic security checklists. Prioritize risks by likelihood and impact, not just listing every possible threat. Include concrete remediation steps with estimated effort. The incident response plan should be actionable enough to follow during an actual security event.", "sections": [{"name": "Product Overview", "guidelines": "Foundation for the security assessment — what is being assessed.\n\n### Product Description\n- Core functionality and target users\n- Distinguishing features that create unique security needs\n- Potential attack vectors specific to this product\n\n### Technical Architecture\n- Programming languages, frameworks, and key libraries\n- Infrastructure: cloud provider, hosting model (containers, serverless, VMs)\n- Network architecture: public endpoints, internal services, VPNs\n\n### Dependencies\n- Third-party services, APIs, and libraries\n- Known vulnerabilities in dependencies (check npm audit, Dependabot, etc.)\n- SLA and security posture of critical vendors\n\n### Deployment Environment\n- On-premises / Cloud / Hybrid\n- Environment isolation (prod, staging, dev)\n- Secrets management approach"}, {"name": "Data Security", "guidelines": "How sensitive data is protected at rest, in transit, and in use.\n\n### Data Classification\n- Critical: Passwords, tokens, payment info, API keys\n- Sensitive: PII (email, name, phone), health data, financial records\n- Internal: Business logic, analytics, logs\n- Public: Marketing content, public API docs\n\n### Protection Measures\n- Encryption at rest: Database encryption, column-level encryption\n- Encryption in transit: TLS version and configuration\n- Hashing: Password hashing algorithm (bcrypt, argon2, scrypt)\n- Tokenization: Payment data or other sensitive fields\n- Data integrity: Checksums, audit trails, backup verification\n\n### Privacy & Compliance\n- GDPR, CCPA, HIPAA, SOC 2 applicability\n- Data retention policies and automated deletion\n- Right to deletion / data export process\n- Data processing agreements with vendors"}, {"name": "Authentication & Authorization", "guidelines": "How users prove who they are and what they can access.\n\n### Authentication\n- Methods: Password, OAuth, SSO, magic link, MFA\n- Session management: Token type (JWT, session cookies), expiration, refresh\n- Password policy: Minimum length, complexity, breach checking\n- Rate limiting: Login attempts, account lockout policy\n### Authorization\n- Model: RBAC, ABAC, or custom\n- Roles: List each role and its permissions\n- Enforcement: Where access control is checked (middleware, API, database RLS)\n- Principle of least privilege: How it is applied\n\n### API Security\n- API key management and rotation\n- OAuth scopes and token permissions\n- Rate limiting and throttling per endpoint"}, {"name": "Threat Analysis & Risk Assessment", "guidelines": "Identifying, evaluating, and prioritizing security risks.\n\n### Threat Model\nFor each threat category:\n- Threat: [Description]\n- Attack vector: [How an attacker would exploit this]\n- Likelihood: Low / Medium / High\n- Impact: Low / Medium / High\n- Current controls: [What is already in place]\n\n### Common Threats to Assess\n- Injection: SQL injection, XSS, command injection\n- Authentication bypass: Broken auth, session hijacking\n- Data exposure: Sensitive data in logs, error messages, APIs\n- Access control: Privilege escalation, IDOR\n- Supply chain: Compromised dependencies, malicious packages\n- Infrastructure: Misconfigured cloud services, exposed ports\n\n### Risk Prioritization\nRank risks by (likelihood × impact) to focus remediation efforts."}, {"name": "Security Controls & Monitoring", "guidelines": "Defensive measures and ongoing security operations.\n\n### Preventive Controls\n- Input validation and sanitization strategy\n- Content Security Policy (CSP) headers\n- CORS configuration\n- Dependency scanning (Snyk, npm audit, Dependabot)\n- Code review security checklist\n\n### Detective Controls\n- Logging: What security events are logged and where\n- Monitoring: Real-time alerting on suspicious activity\n- Audit trails: Who changed what, when, from where\n- Vulnerability scanning: Frequency and tools used\n\n### Security Testing\n- Static analysis (SAST): Tools and CI integration\n- Dynamic analysis (DAST): Penetration testing schedule\n- Bug bounty program: If applicable, scope and rewards"}, {"name": "Incident Response & Business Continuity", "guidelines": "What happens when something goes wrong.\n\n### Incident Response Plan\n- Detection: How incidents are identified (alerts, reports, monitoring)\n- Triage: Severity classification (P0-P3) and response times\n- Containment: Immediate steps to limit damage\n- Communication: Who is notified, internal and external disclosure\n- Recovery: Steps to restore normal operations\n- Post-mortem: Root cause analysis and prevention\n\n### Contacts\n| Role | Person | Contact |\n|------|--------|--------|\n| Security lead | [Name] | [Email/phone] |\n| Engineering on-call | [Name] | [Pager] |\n| Legal/compliance | [Name] | [Email] |\n| Communications | [Name] | [Email] |\n\n### Business Continuity\n- Backup strategy: Frequency, retention, tested recovery time\n- Disaster recovery: RTO and RPO targets\n- Failover: Redundancy and auto-scaling configuration\n\n### Remediation Priorities\nSummary of the most critical vulnerabilities found in this assessment with remediation timelines and owners."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Product Security Assessment$name$;

UPDATE public.prd_templates
SET description = $desc$A comprehensive template for defining and detailing the strategy for a product, including vision, market analysis, objectives, strategies, and roadmap.$desc$,
    structure = $json${"instructions": "Think long-term and connect every section back to the product vision. Market analysis should include specific data and trends, not generic industry observations. OKRs should ladder clearly from vision to measurable outcomes. The roadmap should explain sequencing rationale — why this order matters. Avoid filler; every section should contain decisions or insights that change behavior.", "sections": [{"name": "Product Vision & Mission", "guidelines": "The overarching purpose and long-term aspiration of the product.\n\n### Vision\nThe future state your product is working toward. This should be:\n- Ambitious and inspiring — paints a picture of the world you want to create\n- Aligned with the company’s broader vision\n- Stable over years, not quarters\n\n### Mission\nWhat your product does today to move toward that vision:\n- Who you serve\n- What value you deliver\n- How you are uniquely positioned to deliver it\n### Example\n- Vision: “Every team ships great products without bureaucracy.”\n- Mission: “We give product teams AI-powered tools to write better specs, align faster, and ship with confidence.”"}, {"name": "Market Analysis", "guidelines": "The landscape your product operates in.\n\n### Industry Trends\n- 3-5 current and emerging trends that affect your product\n- For each: what the trend is, how it affects your market, and your strategic response\n\n### Competitor Analysis\nFor each key competitor:\n- Name: What they do\n- Strengths: Where they excel\n- Weaknesses: Where they fall short\n- Your advantage: Why customers choose you instead\n\n### Target Audience\n- Primary segment: Who they are, what they need, how large the segment is\n- Secondary segment: Who else benefits from your product\n- Underserved needs: Gaps in the market that your product can fill\n\n### Market Size\n- TAM / SAM / SOM: With sources and methodology"}, {"name": "Objectives & Key Results", "guidelines": "Precise, measurable goals for the strategy period.\n\n### Objectives\nFor each objective:\n- Objective: [Ambitious, time-bound goal aligned with the vision]\n- Timeframe: [Quarter or year]\n- Owner: [Who is accountable]\n\n### Key Results\nFor each objective, 2-4 measurable results:\n- KR1: [Metric] from [baseline] to [target] by [date]\n- KR2: [Metric] from [baseline] to [target] by [date]\n\n### Alignment\nHow these OKRs connect to:\n- Company-level objectives\n- Cross-functional team goals\n- Revenue and growth targets"}, {"name": "Product Strategies", "guidelines": "Strategic approaches across product, marketing, and customer success.\n\n### Product Development Strategy\n- Key bets: The 2-3 biggest things you are building and why\n- Build vs. buy vs. partner decisions\n- Technical investments (platform, infrastructure, AI/ML)\n- UX/UI evolution direction\n\n### Marketing & Sales Strategy\n- Positioning and messaging approach\n- Key channels and campaigns\n- Sales motion (self-serve, sales-assisted, enterprise)\n- Pricing strategy and evolution\n\n### Customer Success Strategy\n- Onboarding and activation approach\n- Retention and expansion playbook\n- Support model and escalation paths\n- Community and education programs"}, {"name": "Product Roadmap", "guidelines": "A time-bound plan showing what gets built and when.\n\n### Near-Term (This Quarter)\nFor each initiative:\n- Initiative: [Name]\n- Goal: [What it achieves]\n- Status: Not started / In progress / Complete\n- Dependencies: [What it needs]\n\n### Medium-Term (Next 2 Quarters)\n- Planned initiatives with rationale and rough sizing\n- Key milestones and checkpoints\n\n### Long-Term (6-12 Months)\n- Strategic bets and exploration areas\n- Technology investments\n- Market expansion plans\n\n### Sequencing Rationale\nWhy this order? What must come first to enable what comes later?"}, {"name": "Risks & Success Criteria", "guidelines": "What could derail the strategy and how you will measure progress.\n\n### Key Risks\nFor each risk:\n- Risk: [What could go wrong]\n- Likelihood: Low / Medium / High\n- Impact: Low / Medium / High\n- Mitigation: [How to prevent or reduce]\n\n### Strategy Success Criteria\nHow you will know the strategy is working at the 3, 6, and 12 month mark:\n- 3 months: [Early signals and leading indicators]\n- 6 months: [Meaningful progress markers]\n- 12 months: [Outcome-level results]\n\n### Review Cadence\nWhen and how the strategy will be reviewed and updated."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Product Strategy Document$name$;

UPDATE public.prd_templates
SET description = $desc$Plan a codebase refactor with clear motivation, target architecture, migration steps, and risk assessment. Keeps large refactors organized and prevents the common trap of refactoring without a finish line.$desc$,
    structure = $json${"instructions": "Write this as a pragmatic engineering plan, not an aspirational architecture doc. The current state section should be honest about what is actually wrong — with specific examples of pain points, not vague complaints. The target state should be concrete enough to validate when you’re done. Migration steps should be ordered so each step leaves the codebase in a working state. Timebox the effort — refactors without deadlines never finish. Be explicit about what is NOT being refactored.", "sections": [{"name": "Current State", "guidelines": "What exists today and what is specifically wrong with it.\n\n### Problem Areas\nFor each problem, be concrete:\n- Area: [Module/file/pattern]\n- What’s wrong: [Specific issue — not “it’s messy” but “3 different auth patterns across 12 files”]\n- Impact: [Build time, error rate, developer confusion, incidents caused]\n\n### Quantified Pain\n- Build/deploy time: X minutes\n- Incident frequency: X per month related to this area\n- Developer hours wasted: X hours/week\n- Code duplication: X instances of similar logic"}, {"name": "Target State", "guidelines": "What the code looks like when the refactor is done.\n\n### Architecture Changes\nDescribe the new patterns, abstractions, or structure at a level specific enough to know when you’re done.\n\n### Before → After\n- Before: [Current pattern with specific example]\n- After: [New pattern with specific example]\n\n### Completion Criteria\nObjectively verifiable — not “code is cleaner” but:\n- [ ] All API routes use the new middleware pattern\n- [ ] Zero instances of the deprecated oldFunction() remain\n- [ ] All database queries go through the repository layer\n- [ ] Test coverage for refactored modules is above X%"}, {"name": "Motivation & Urgency", "guidelines": "### Why Now\nThe trigger that made this the right time:\n- Blocked feature? Scaling issue? Recurring incidents? Team growing?\n\n### Business Case\n- Cost of NOT refactoring: [Quantified: incidents, velocity loss, hiring friction]\n- Value of refactoring: [What it unblocks: features, performance, team speed]\n- Time investment: [Estimated effort in days/weeks]\n- Break-even: [When the investment pays off]\n\n### Stakeholder Alignment\nWho needs to approve this and what they care about (timeline impact, risk, feature delay)."}, {"name": "Scope & Boundaries", "guidelines": "### In Scope\nExplicitly list what IS being changed:\n- Files/modules: [list]\n- Patterns/abstractions: [list]\n- Dependencies: [list]\n\n### Out of Scope\nExplicitly list what is NOT being changed and why:\n- [Module X]: Not touched because [reason]\n- [Pattern Y]: Separate refactor planned for [timeframe]\n\n### Phases\nIf the refactor can be broken into independent phases:\n- Phase 1: [Scope] → [Deliverable] → [Can ship independently: yes/no]\n- Phase 2: [Scope] → [Deliverable]\n- Phase 3: [Scope] → [Deliverable]"}, {"name": "Migration Strategy", "guidelines": "How to get from current → target state while keeping the system working throughout.\n\n### Approach\n- Strangler fig: New pattern alongside old, gradually migrate callers\n- Big bang: One switchover (higher risk, faster completion)\n- Incremental: Gradual replacement file by file\n\n### Coexistence Plan\nIf old and new patterns coexist temporarily:\n- How are they distinguished? (naming convention, directory, feature flag)\n- How long will both exist?\n- What prevents new code from using the old pattern?\n\n### Data Migration\nIf schema or data format changes:\n- Migration script approach\n- Backfill strategy\n- Rollback capability"}, {"name": "Implementation Steps", "guidelines": "Ordered list of concrete steps. Each step should leave the codebase in a working, deployable state.\n\n### Format\n\nStep 1: [Short description]\nFiles: [list of files changed]\nMigration: [any schema changes]\nVerification: [how to confirm it works]\nPR size: [small/medium/large]\n\n\n### Step Sequence\n1. [First change — usually the new abstraction/pattern]\n2. [Migrate highest-value or highest-risk area first]\n3. [Continue migration area by area]\n4. [Remove old code and dead paths]\n5. [Update documentation and tests]\n\nFlag any steps that require team coordination or have deploy ordering constraints."}, {"name": "Risk Assessment & Rollback", "guidelines": "### Risk Matrix\nFor each risk:\n- Risk: What could go wrong\n- Likelihood: Low / Medium / High\n- Impact: Low / Medium / High\n- Mitigation: How to prevent or detect early\n- Rollback: How to revert if it happens\n\n### Common Risks\n- Data loss during migration\n- Broken integrations with external services\n- Performance regression under production load\n- Blocked feature work during refactor\n\n### Monitoring\n- Error rates to watch during/after deploy\n- Performance metrics to compare before/after\n- Alerts to set up before starting\n\n### Point of No Return\nIdentify any steps that cannot be easily reversed (schema migrations, data transformations) and what safeguards to put in place."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Refactoring Plan$name$;

UPDATE public.prd_templates
SET description = $desc$A template for documenting key updates in a software release, including features, bug fixes, and known issues.$desc$,
    structure = $json${"instructions": "Fill in each section with specific details relevant to the release being documented.", "sections": [{"name": "Release Information", "guidelines": "### Metadata\n- Product: [Product name]\n- Version: [X.Y.Z]\n- Release date: [Date]\n- Release type: Major / Minor / Patch / Hotfix\n\n### Summary\nOne paragraph summarizing what this release delivers and who it’s for. Lead with the most impactful change."}, {"name": "New Features", "guidelines": "Features and capabilities added in this release.\n\n### Format for Each Feature\n[Feature Name]\n[1-2 sentence description of what it does and why it matters to users.]\n\n### Guidelines\n- Lead with the user benefit, not the technical implementation\n- Include a screenshot or GIF if the feature is visual\n- Note if a feature is in beta, behind a feature flag, or limited to certain plans\n- If no new features, state: “No new features in this release.”"}, {"name": "Improvements", "guidelines": "Enhancements to existing features — performance gains, UX polish, and quality-of-life changes.\n\n### Format\n- [Area]: [What improved and why it matters]\n\n### Examples\n- Dashboard loading: Reduced load time from 3s to 800ms\n- Search: Now supports partial matching and highlights results\n- Mobile: Improved touch targets and navigation on small screens\n\nIf no improvements, state: “No improvements in this release.”"}, {"name": "Bug Fixes", "guidelines": "Bugs resolved in this release.\n\n### Format\n- [Bug summary]: [What was fixed and when it was introduced if known]\n\n### Guidelines\n- Write from the user’s perspective: “Fixed an issue where [user action] would [broken behavior]”\n- Group by area (UI, API, Performance, etc.) if there are many\n- For security fixes, note the severity without disclosing exploit details\n\nIf no bug fixes, state: “No bug fixes in this release.”"}, {"name": "Known Issues", "guidelines": "Issues the team is aware of but not yet resolved.\n\n### Format\nFor each issue:\n- Issue: [Description of the problem]\n- Impact: [Who is affected and how]\n- Workaround: [Temporary solution if one exists]\n- Status: Investigating / In progress / Planned for [version]\n\nIf no known issues, state: “No known issues.”"}, {"name": "Breaking Changes & Migration", "guidelines": "Changes that require user action or may affect existing workflows.\n\n### Format\n[What changed]\n- Before: [Previous behavior]\n- After: [New behavior]\n- Action required: [What users need to do]\n- Deadline: [When the old behavior will be removed, if applicable]\n\n### Deprecations\nFeatures or APIs that are deprecated and will be removed in a future release.\n\nIf no breaking changes, state: “No breaking changes in this release.”"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Release Notes$name$;

UPDATE public.prd_templates
SET description = $desc$Strategy for conducting user testing to validate product features and ensure a smooth user experience.$desc$,
    structure = $json${"instructions": "Design a practical testing plan that will actually inform product decisions. Test scenarios should reflect real user workflows, not contrived tasks. Include specific questions for post-task interviews. Metrics should be directly tied to ship/no-ship decisions. Describe what changes would be made based on different outcome ranges.", "sections": [{"name": "Test Objectives", "guidelines": "What you want to learn from this test — not what you want to prove.\n\n### Primary Questions\n1. Can users successfully [complete key task] without assistance?\n2. Where do users get confused or stuck?\n3. Does the [feature/flow] match users’ mental model?\n\n### Success Criteria\nDefine specific thresholds that determine pass/fail:\n- Task completion rate: > [X]%\n- Time on task: < [X] minutes\n- Error rate: < [X]%\n- Satisfaction score: > [X]/7"}, {"name": "Participant Criteria", "guidelines": "Who to recruit for the test.\n\n### Target Profile\n- Number of participants: 5-8 per user segment\n- Key demographics: Role, experience level, industry\n- Required experience: Familiarity with [tool/workflow/domain]\n- Exclusions: People who [shouldn’t be included and why]\n\n### Recruitment\n- Source: Customer list, user panel, recruitment service, social media\n- Screening questions: 3-5 questions to qualify participants\n- Incentive: What participants receive for their time"}, {"name": "Test Scenarios", "guidelines": "Realistic scenarios that set context for the tasks — not step-by-step instructions.\n\n### Format\nScenario [#]: [Name]\nImagine you are [role/context]. You need to [goal]. [Additional context that makes it realistic].\n\n### Guidelines\n- Scenarios should reflect actual use cases from user research\n- Don’t hint at the UI — describe the goal, not the steps\n- Include one ‘easy’ scenario and one ‘challenging’ scenario\n- Cover both first-time and repeat usage if relevant"}, {"name": "Tasks", "guidelines": "Specific tasks participants will complete within each scenario.\n\n### Format\nTask [#]: [What the participant should accomplish]\n- Scenario: Which scenario this belongs to\n- Starting point: Where the user begins (specific URL/screen)\n- Success criteria: How you know they completed it\n- Time limit: Maximum time before moving on\n\n### Task Types\n- Discovery tasks: Can you find [information]?\n- Completion tasks: Complete [workflow] end to end\n- Comparison tasks: Which of these options would you choose?\n- Open-ended tasks: How would you approach [goal]?"}, {"name": "Metrics for Success", "guidelines": "Quantitative and qualitative measures to evaluate the test results.\n\n### Quantitative Metrics\n- Task completion rate: % who complete each task successfully\n- Time on task: Average and range for each task\n- Error rate: Number and types of errors per task\n- Clicks/steps: Number of actions to complete each task\n- SUS/satisfaction score: Post-test questionnaire results\n\n### Qualitative Metrics\n- Think-aloud observations: Confusion points, expressed frustrations\n- Feature discovery: Did users notice [feature] without prompting?\n- Mental model fit: Did the interface match user expectations?\n- Emotional response: Confidence, frustration, delight at key moments"}, {"name": "Feedback Collection", "guidelines": "How data will be gathered during and after the test.\n\n### During the Test\n- Think-aloud protocol: Participant narrates their thought process\n- Screen recording: Capture all interactions and mouse movements\n- Observer notes: Facilitator and observers capture key moments\n- Task timing: Start/stop times for each task\n\n### Post-Test\n- Questionnaire: SUS, NPS, or custom satisfaction survey\n- Debrief interview: 5-10 open-ended questions about the experience\n- Preference ranking: If testing multiple designs, rank preference\n\n### Tools\nSpecify the usability testing tools: UserTesting, Maze, Lookback, Zoom, etc."}, {"name": "Analysis & Recommendations", "guidelines": "How findings will be analyzed and turned into product decisions.\n### Analysis Framework\n- Severity rating for each finding: Critical / Major / Minor / Cosmetic\n- Frequency: How many participants encountered each issue\n- Impact: Effect on task completion and user satisfaction\n\n### Deliverables\n- Findings report: Summary of all issues with severity and frequency\n- Highlight reel: 3-5 minute video of key moments for stakeholders\n- Recommendations: Prioritized list of changes to make\n\n### Decision Framework\n- Critical findings: Must fix before launch\n- Major findings: Fix in next sprint\n- Minor findings: Add to backlog\n- No issues found: Validate with larger sample or proceed"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$User Testing Plan$name$;

UPDATE public.prd_templates
SET description = $desc$Aakash Gupta's PRD template (shared with permission)$desc$,
    structure = $json${"instructions": "Be evidence-driven and specific throughout. Every claim should reference data, user research, or market insight. Prioritize crisp problem statements and measurable goals over lengthy narratives. The impact sizing model should include actual calculations with stated assumptions. Key flows should be detailed enough that a designer or engineer could build from them without further clarification.", "sections": [{"name": "Problem", "guidelines": "Describe the problem in 1-2 sentences. Someone should be able to read this and communicate the customer and business value + risks.\n\n### Guidelines\n- State the problem as a hypothesis you can test\n- Highlight evidence or insights that support this\n- Include both the customer pain and the business opportunity\n- Be specific: “Users churn after 7 days because they never find [feature]” not “engagement is low”"}, {"name": "High Level Approach", "guidelines": "The rough shape of how you might tackle the problem. A few sentences max.\n\n### Guidelines\n- Describe the approach, not the full solution\n- This should communicate direction to the team without over-constraining design\n- Think of it as: “We’re going to solve this by [approach], roughly by [method]”"}, {"name": "Narrative", "guidelines": "Hypothetical stories that paint a picture of what life looks like for customers today.\n\n### Include\n- Common use case: The typical user scenario (80% of usage)\n- Edge case: An unusual but important scenario that tests the solution\n- Before/after: What life looks like without your solution vs. with it\n\nStories should create empathy and help the team internalize user needs. Make them vivid and specific."}, {"name": "Goals", "guidelines": "High-level goals, ideally in priority order.\n\n### Measurable Goals\nGoals with concrete metrics:\n- Goal 1: [Metric] from [baseline] to [target]\n- Goal 2: [Metric] from [baseline] to [target]\n\n### Immeasurable Goals\nGoals about how the experience should *feel*:\n- Users should feel [confident/delighted/empowered] when [doing action]\n- The experience should feel [fast/simple/professional]\n\nKeep it short — 3-5 goals max, in priority order."}, {"name": "Metrics", "guidelines": "Specific, operationalized metrics to track success.\n\n### North Star Metric\nThe single most important metric:\n- Metric: [Name]\n- Current baseline: [Value]\n- Target: [Value]\n- Measurement: How and where this is tracked\n\n### Secondary Metrics\nSupporting metrics that indicate progress:\n- [Metric 2]: [Baseline] → [Target]\n- [Metric 3]: [Baseline] → [Target]\n\n### Guardrail Metrics\nMetrics that must NOT degrade:\n- [Guardrail metric]: Must stay above [threshold]\n- State what amount of movement would be unacceptable and trigger a rollback"}, {"name": "Impact Sizing Model", "guidelines": "A quantitative model estimating the impact on key metrics.\n\n### Calculation\nShow your work step by step:\n1. [Input assumption]: [Number] — source: [where this comes from]\n2. [Input assumption]: [Number] — source: [where this comes from]\n3. [Calculation step]: [Formula] = [Result]\n4. [Final estimate]: Expected impact on north star metric\n\n### Revenue/Bottom-Line Impact\n- Estimated impact on revenue or profit\n- Confidence level: Low / Medium / High\n- Key assumptions that could change the estimate"}, {"name": "Non-goals", "guidelines": "Explicit areas you do NOT plan to address.\n### Format\nFor each non-goal:\n- Not doing: [What you’re skipping]\n- Why: [Rationale — too expensive, wrong timing, different team, low impact]\n\n### Guidelines\n- Non-goals are as important as goals — they prevent scope creep\n- If someone might reasonably assume it’s in scope, call it out as a non-goal\n- Include things you considered but explicitly decided against"}, {"name": "Solution Alignment", "guidelines": "Draw the perimeter of the solution. Do not force others to identify scope.\n\n### What’s In\n- Core experience that MUST be built\n- Quality bar for the initial release\n\n### What’s Out\n- Features saved for later\n- Quality tradeoffs you’re accepting for now\n\n### Open Questions\n- Decisions that still need input from design/engineering\n- Areas where you’re deliberately leaving room for the team to explore"}, {"name": "Key Features: Plan of Record", "guidelines": "The features that shape the solution, in priority order.\n\n### Format\nFor each feature:\n- Feature: [Name]\n- Priority: P0 (must ship) / P1 (should ship) / P2 (stretch)\n- Description: What it does and why it matters\n- Size estimate: Small / Medium / Large\n\n### Guidelines\n- Think of this as drawing the perimeter of the solution space\n- Challenge each feature: can a smaller version be shipped independently?\n- The team fills in the details — you define the boundaries"}, {"name": "Future Considerations", "guidelines": "Features you are saving for later that might inform how you build now.\n\n### Planned Follow-ups\n- Feature: [Description] — Planned for [timeframe/phase]\n- Feature: [Description] — Planned for [timeframe/phase]\n\n### Build-Now Implications\nAnything about these future features that should influence current architecture or design decisions. Example: “We’ll add multi-language support in Q3, so don’t hard-code strings.”"}, {"name": "Key Flows", "guidelines": "End-to-end experience shown screen by screen. Get detailed here — not high level.\n\n### Format\nFlow: [Name]\n1. Screen: [Page/view name]\n- User sees: [What’s on screen]\n- User does: [Action they take]\n- Result: [What happens next]\n2. Screen: [Next page/view]\n- ...\n\n### Guidelines\n- Walk through every click, not just the high-level steps\n- Include empty states, loading states, and error states\n- An engineer should be able to build from this without asking questions"}, {"name": "Key Logic", "guidelines": "Business rules that guide design and development.\n\n### Rules\nFor each rule:\n- Rule: [Clear statement of the logic]\n- Applies when: [Conditions]\n- Example: [Concrete scenario]\n\n### Edge Cases\n- What happens when [boundary condition]?\n- What happens when [unusual input]?\n- What happens when [concurrent action]?\n\nMake it so an engineer feels everything is thought through."}, {"name": "Launch Plan", "guidelines": "How this product gets to market.\n\n### Phases\nFor each phase:\n- Phase: [Name] — [Purpose]\n- Entry criteria: What must be true to start this phase\n- Exit criteria: What must be true to move to the next phase\n- Duration: Expected timeline\n\n### Experiment Design (if applicable)\n- Type: A/B test, staged rollout, beta program\n- Sample size: Users needed for statistical significance\n- Duration: Time needed based on north star metric goal\n- Success criteria: What metric movement triggers full launch\n\n### Risks & Dependencies\n- Risks that can throw a wrench in timelines\n- Dependencies on other teams or external factors\n- Contingency plans for each"}, {"name": "Key Milestones", "guidelines": "The critical checkpoints from now to launch.\n\n### Format\n| Milestone | Date | Owner | Status |\n|-----------|------|-------|--------|\n| Design complete | [Date] | [Name] | [Status] |\n| Engineering kickoff | [Date] | [Name] | [Status] |\n| Internal dogfood | [Date] | [Name] | [Status] |\n| Beta launch | [Date] | [Name] | [Status] |\n| GA launch | [Date] | [Name] | [Status] |\n\n### Dependencies\nCall out any milestone that blocks another or depends on an external team."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Aakash's PRD$name$;

UPDATE public.prd_templates
SET description = $desc$A powerful strategy tool from Jake Knapp and John Zeratsky, creators of the Design Sprint, introduced in Click via Lenny’s Newsletter. The Founding Hypothesis helps teams align on the basics—customer, problem, approach, competitors, and differentiation—to craft a clear, testable foundation for any new product or initiative.$desc$,
    structure = $json${"instructions": "Use this template to clearly define the customer’s problem, our approach to solving it, and how our solution stands out from competitors. DO NOT make this too long Return in the format\n\nIf we help [customer]\nsolve [problem]\nwith [approach],\nthey will choose it over [competitors]\nbecause our solution is [differentiation].", "sections": [{"name": "Customer Identification", "guidelines": "Identify the specific customer or segment experiencing the problem.\n\n### Be Specific\n- Not “businesses” but “B2B SaaS companies with 10-50 employees”\n- Not “developers” but “frontend engineers building React apps”\n- Include their role, company stage, and what they care about most\n\n### Validation\n- How do you know these are your customers?\n- Have you talked to them? How many?\n- What evidence supports this customer choice?"}, {"name": "Problem Definition", "guidelines": "Describe the problem the customer faces in specific, measurable terms.\n\n### Guidelines\n- State the problem from the customer’s perspective, not yours\n- Quantify the pain: time wasted, money lost, frequency of occurrence\n- Distinguish between the root problem and symptoms\n\n### Format\n[Customers] currently struggle with [specific problem], which causes [measurable consequence]. Today they cope by [current workaround], which is inadequate because [limitation]."}, {"name": "Solution Approach", "guidelines": "How you will solve the problem — the “what” at a high level.\n\n### Guidelines\n- Describe the approach, not every feature\n- Explain why THIS approach vs. alternatives you considered\n- Be honest about what is novel vs. what is table stakes\n\n### Format\nWe will [approach] by [method], which solves the problem because [reasoning]. We chose this over [alternatives] because [tradeoff rationale]."}, {"name": "Competitive Analysis", "guidelines": "Who else solves this problem and why customers would choose you.\n\n### Competitors\nFor each competitor or alternative (including “do nothing”):\n- Name: What they offer\n- Strengths: What they do well\n- Weaknesses: Where they fall short\n- Why customers switch: What triggers leaving them\n\n### Differentiation\nThe specific reasons a customer would choose your solution over every alternative listed above."}, {"name": "Differentiation Strategy", "guidelines": "What makes your solution uniquely valuable — your unfair advantage.\n\n### Types of Differentiation\n- Experience: 10x better UX for the specific use case\n- Speed: Dramatically faster to start or complete the task\n- Price: Significantly cheaper or different pricing model\n- Integration: Works where your customers already are\n- Technology: Unique capability competitors can’t easily replicate\n\n### The Hypothesis\nComplete the sentence:\n\nIf we help [customer] solve [problem] with [approach], they will choose it over [competitors] because our solution is [differentiation]."}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Founding Hypothesis$name$;

UPDATE public.prd_templates
SET description = $desc$Lenny Rachitsky's 1-pager (shared with permission). Useful when you already have a product in mind.$desc$,
    structure = $json${"instructions": "Keep this genuinely short — it’s a 1-pager, not a comprehensive PRD. Be direct and opinionated rather than exhaustive. The problem should be a single testable hypothesis. Evidence should be 3-5 strong data points. The solution should describe what users experience, not internal architecture. Every section earns its place by being essential to the decision.", "sections": [{"name": "Description", "guidelines": "What is the product? A brief description so readers can quickly grasp what this project is about.\n\n### Guidelines\n- 2-3 sentences maximum\n- A stranger should understand the product after reading this\n- Avoid jargon and internal codenames\n- Answer: What does it do? Who is it for?"}, {"name": "Problem", "guidelines": "The problem as a testable hypothesis. You’ll add evidence in the next section.\n### Strong Problem Statement Attributes\n- Short: Aim for a single sentence\n- Focused: A single clear problem, owned by one team, solvable in a reasonable time\n- Need-based: References an unmet need (Jobs-To-Be-Done is useful here)\n- Has a what AND a why: What’s going wrong, and why it matters\n- Solution-agnostic: Resist jumping to a solution this early\n\n### Examples\n- *Good*: “Lyft drivers are cancelling rides too often because the passengers are too far away.”\n- *Good*: “Users are dropping off at too high a rate at the final step of the signup flow.”\n- *Bad*: “User growth is slowing.” (too broad, not user-centric)\n- *Bad*: “Build a loyalty program.” (assumes a solution)\n- *Bad*: “Users are bouncing from the signup flow.” (not focused enough, missing the ‘why’)"}, {"name": "Why", "guidelines": "How do we know this is a real problem worth solving? Back up your hypothesis.\n\n### Evidence\nCollect 3-5 strong data points. Quality over quantity:\n- Quantitative: Metrics, funnel data, churn analysis, survey results\n- Qualitative: User interviews, support tickets, session recordings\n- Market signals: Competitor moves, industry trends, analyst reports\n\n### Devil’s Advocate\nTry to convince yourself this ISN’T a real or big enough problem:\n- What gaps exist in your evidence?\n- Is the evidence truly telling you what you think?\n- Could there be a simpler explanation?\n\nYour case doesn’t have to be airtight — but acknowledge the gaps."}, {"name": "Success", "guidelines": "How do we know if we’ve solved this problem?\n\n### Ideal Success Criteria\n- Specific metric: [Metric name]\n- Defined goal: [X]% increase/decrease\n- Measurable: Can be tracked with current tooling\n- Connected to KPIs: Ties to your team’s goals\n- Based on data: Informed by opportunity size and past experiments\n\n### Guidelines\n- Try hard to make it a concrete number: “10% increase in X,” “50% decrease in Y”\n- Pick a goal that’s believable but ambitious — one your team and leaders would be excited about\n- If a metric truly doesn’t make sense, describe what the world looks like if this is a big success"}, {"name": "Audience", "guidelines": "Who are we building for? It should rarely be “all users.”\n\n### Specifics\n- User segment: New vs. returning? Casual vs. power? Free vs. paid?\n- Platform: Mobile, web, both?\n- Geography: All markets or specific regions?\n- Size of segment: What % of your user base does this represent?\n\n### Why This Segment\nWhy focus here first? Biggest pain, largest opportunity, most strategic, etc."}, {"name": "What", "guidelines": "Roughly, what does the solution look like in the product?\n\n### Guidelines\n- Describe what users will experience, not internal architecture\n- Be as detailed as your team needs (depends on how much is already known)\n- Include rough mockups, wireframes, or references if available\n- Highlight the key interaction moments and any major UX decisions\n\n### Format\nWalk through the core experience:\n1. User starts at [context]\n2. They see/do [interaction]\n3. The result is [outcome]"}, {"name": "How", "guidelines": "How will we build or test this?\n\n### Approach\n- Build: Full implementation, ship to all users\n- Experiment: A/B test with defined success criteria\n- Prototype: Quick test to validate before full build\n- Manual first: Do it manually to learn before automating\n\n### Technical Considerations\n- Major technical decisions or constraints\n- Dependencies on other teams or systems\n- Known risks or unknowns"}, {"name": "When", "guidelines": "When does it ship and what are the milestones?\n\n### Timeline\n| Milestone | Target Date | Owner |\n|-----------|-------------|-------|\n| Design complete | [Date] | [Name] |\n| Build complete | [Date] | [Name] |\n| Internal testing | [Date] | [Name] |\n| Ship / Experiment start | [Date] | [Name] |\n| Results review | [Date] | [Name] |\n\n### Confidence Level\nHow confident are you in this timeline? What could slip and why?"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Lenny's 1-Pager$name$;

UPDATE public.prd_templates
SET description = $desc$Peter Yang's PRD template (shared with permission)$desc$,
    structure = $json${"instructions": "Prioritize clarity and focus — this template works best when concise. The problem section needs concrete evidence (data, user quotes, or research). Write requirements as user stories with clear priority levels (P0 vs P1). The launch plan should specify experiment design with measurable success criteria and a ramp plan.", "sections": [{"name": "Team", "guidelines": "List the people involved and their roles.\n\n### Format\n| Role | Name |\n|------|------|\n| PM | [Name] |\n| Design | [Name] |\n| Engineering Lead | [Name] |\n| Analytics | [Name] |\n| Marketing | [Name] |\n\nInclude anyone with decision-making authority or a key deliverable."}, {"name": "Problem", "guidelines": "The customer problem you’re solving — with evidence that it’s real.\n\n### Format\nWho: [Specific customer segment]\nProblem: [What they struggle with]\nEvidence: [How you know — data, research, support tickets]\n\n### Example (Pinterest topic selector)\n*New users want to see topics they’re interested in when they first sign up. Today, all new users see the same feed of popular content dominated by a few categories like women’s fashion and decor that don’t match the diverse interests of all new users.*\n\n### Guidelines\n- Be specific about who the customer is\n- Link to customer research and data\n- The problem should be clear enough that anyone on the team can explain it"}, {"name": "Goals", "guidelines": "One output goal and 2-3 input metrics that drive it.\n\n### Output Goal\nThe single metric that defines success:\n- Metric: [Name]\n- Target: [X]% change from [baseline]\n- Timeframe: [Period]\n\n### Input Metrics\nLeading indicators that drive the output:\n- Input 1: [Metric and target]\n- Input 2: [Metric and target]\n- Input 3: [Metric and target]\n\n### Non-Goals (Optional)\nThings explicitly out of scope and why.\n\n### Example (Pinterest)\n- Output: Grow activation rate by 20% (% of signups who return within 7 days)\n- Inputs: # users who visit topic selector, # who select a topic, # of topics selected, # who pin during first session"}, {"name": "Requirements", "guidelines": "What the solution looks like, written as user stories with clear priorities.\n\n### High-Level Solution\nDescribe the solution in 2-3 sentences before diving into details.\n\n### Milestones\nIf there are multiple phases, list them clearly with scope for each.\n\n### User Stories\nFor each milestone, write features as user stories:\n- P0 (must ship): As a [user], I want [capability] so that [benefit]\n- P0: As a [user], I want [capability] so that [benefit]\n- P1 (should ship): As a [user], I want [capability] so that [benefit]\n\n### Open Questions\nHighlight any decisions that need async discussion. Tag the person who should weigh in."}, {"name": "Launch Plan", "guidelines": "How the feature gets to users — staged rollout or experiment.\n\n### Experiment Design (if applicable)\n- Success criteria: [Metric] improves by [X]%\n- Eligibility: Who is included in the experiment\n- Test group: [Description of the new experience]\n- Control group: [Description of the current experience]\n- Split: [Percentage split, e.g., 50/50]\n- Duration: [How long to run for statistical significance]\n\n### Rollout Plan\n- Phase 1: [% of users] — Monitor for [duration]\n- Phase 2: [% of users] — Monitor for [duration]\n- Phase 3: 100% — GA launch\n\n### Rollback Criteria\nWhat metric movement would trigger a rollback? Who makes that call?"}]}$json$::jsonb
WHERE is_built_in = true AND name = $name$Peter's PRD$name$;

